def _dedup_in_order(sets: List[List[str]]) -> List[str]:
    """按 proof_ids（批次原序）合并去重多个冲突集合中的标识。"""
    seen = set()
    ordered: List[str] = []
    for conflict_set in sets:
        for proof_id in conflict_set:
            if proof_id not in seen:
                seen.add(proof_id)
                ordered.append(proof_id)
    return ordered

