) -> List[str]:
    """按组内批次原序（``proof_ids``）合并去重冲突集合中的标识。"""
    involved = {proof_id for conflict_set in sets for proof_id in conflict_set}
    return [proof_id for proof_id in proof_ids if proof_id in involved]

